{"command": "cat <<'EOF' > /app/canonicalize.py
import re

METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
PERMS = {"ALLOW", "DENY"}
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def norm_path(p):
    return VAR_RE.sub("{var}", p)


def parse(lines):
    endpoints = []  # (orig_path, norm_path, method, role, perm)
    base = None
    exclude = set()
    plan = []       # (norm_path, method)
    state = 0       # 0=endpoints, 1=base/exclude, 2=plan
    cut = False
    i = 0
    n = len(lines)
    while i < n:
        stripped = lines[i].strip()
        if state == 0:
            if stripped == "":
                state = 1
                i += 1
                while i < n and lines[i].strip() == "":
                    i += 1
                continue
            if not cut:
                fields = stripped.split()
                if len(fields) == 4:
                    p, m, r, perm = fields
                    if p.strip() and m.upper() in METHODS and \
                       perm.upper() in PERMS and r.strip():
                        endpoints.append((p, norm_path(p), m.upper(), r, perm.upper()))
                        i += 1
                        continue
                cut = True
            i += 1
        elif state == 1:
            if stripped == "":
                state = 2
                i += 1
                while i < n and lines[i].strip() == "":
                    i += 1
                continue
            fields = stripped.split()
            if fields and fields[0] == "base" and len(fields) == 2:
                base = fields[1]
            elif fields and fields[0] == "exclude":
                exclude.update(fields[1:])
            i += 1
        else:
            if stripped == "":
                i += 1
                continue
            if not cut:
                fields = stripped.split()
                if len(fields) == 2:
                    p, m = fields
                    if p.strip() and m.upper() in METHODS:
                        plan.append((norm_path(p), m.upper()))
                        i += 1
                        continue
                cut = True
            i += 1
    return endpoints, base, exclude, plan


def seg_count(np):
    return len([s for s in np.split("/") if s])


def main():
    with open("/app/input.txt") as f:
        lines = f.read().split("\n")
    endpoints, base, exclude, plan = parse(lines)

    def base_ok(e):
        return base is None or e[0].startswith(base)

    def eligible(e):
        return base_ok(e) and e[3] not in exclude

    included = set()

    if not plan:
        for i, e in enumerate(endpoints):
            if eligible(e):
                included.add(i)
    else:
        have = {(e[1], e[2]) for e in endpoints}
        for (np, m) in plan:
            if (np, m) not in have:
                continue
            # direct matches
            for i, e in enumerate(endpoints):
                if e[1] == np and e[2] == m and eligible(e):
                    included.add(i)
            # parent paths
            for P in {e[1] for e in endpoints}:
                if P == np or not np.startswith(P):
                    continue
                eps = [i for i, e in enumerate(endpoints) if e[1] == P]
                b_ok = [i for i in eps if base_ok(endpoints[i])]
                elig = [i for i in b_ok if endpoints[i][3] not in exclude]
                if elig:
                    included.update(elig)
                elif b_ok:
                    # only excluded-role endpoints at this parent path
                    included.update(b_ok)

    # dedupe by (norm_path, method, role), first in input order
    seen = {}
    for i in sorted(included):
        e = endpoints[i]
        key = (e[1], e[2], e[3])
        if key not in seen:
            seen[key] = e

    items = list(seen.values())
    items.sort(key=lambda e: (-seg_count(e[1]), e[2], e[3],
                              0 if e[4] == "ALLOW" else 1))

    out_lines = ["{} {} {} {}".format(e[0], e[2], e[3], e[4]) for e in items]
    out = "\n".join(out_lines) + "\n" if out_lines else "\n"
    with open("/app/output.txt", "w") as f:
        f.write(out)


if __name__ == "__main__":
    main()
EOF
echo done"}

